#!/bin/sh
# Regenerates trailer-parody-9x16.html (YouTube Shorts, 1080x1920) from the 4:5 master trailer-parody.html.
# The only difference is the body class; all 9:16 layout lives in the master's "body.r9x16" CSS block and the V/OY/BT/BB switches in its script.
# Run from anywhere:  sh projects/2026-10-13-qsme-build-trailer-parody/motion/sync-9x16.sh
cd "$(dirname "$0")" || exit 1
sed -e 's/<body class="build r4x5">/<body class="build r9x16">/' \
    -e '1a\
<!-- GENERATED by sync-9x16.sh from trailer-parody.html. Do not edit: change the master and re-run the script. -->' \
    trailer-parody.html > trailer-parody-9x16.html
grep -q 'class="build r9x16"' trailer-parody-9x16.html && echo "wrote $(pwd)/trailer-parody-9x16.html"
